/*
 * A297181  a(n) is the smallest positive integer of length (distance from
 *          origin) n in the Cayley graph of the integers generated by all
 *          powers of 11.
 * https://oeis.org/A297181
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(1)=1, a(2)=2, a(3)=3, a(4)=4, a(5)=5, a(6)=6; For n>6: a(n) =
 *            a(n-1) + 11*a(n-5) - 11*a(n-6)
 * Range:     u8 n <= 12, u16 n <= 24, u32 n <= 47, u64 n <= 93, u128 n <= 186,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    static seq_t *cache = NULL;        /* one‑based values stored at cache[i-1] */
    static size_t cache_len = 0;       /* number of stored values */
    static size_t cache_cap = 0;       /* allocated capacity */

    if (n == 0) return 0;              /* behavior below offset is irrelevant */

    /* Ensure storage for at least n elements */
    if (cache_cap < (size_t)n) {
        size_t new_cap = cache_cap ? cache_cap : 16;
        while (new_cap < (size_t)n) new_cap <<= 1;
        seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        cache = tmp;
        cache_cap = new_cap;
    }

    /* Fill missing initial values a(1)…a(6) */
    if (cache_len < 6) {
        size_t upto = n < 6 ? (size_t)n : 6;
        for (idx_t i = cache_len + 1; i <= (idx_t)upto; ++i) {
            cache[i - 1] = (seq_t)i;
        }
        if (upto > cache_len) cache_len = upto;
    }

    /* Compute missing recurrence values */
    if (cache_len < (size_t)n) {
        for (idx_t i = cache_len + 1; i <= n; ++i) {
            seq_t val;
            if (i <= 6) {
                val = (seq_t)i;
            } else {
                /* a(i) = a(i-1) + 11*a(i-5) - 11*a(i-6) */
                seq_t term1 = cache[i - 2];   /* a(i-1)   */
                seq_t term2 = cache[i - 6];   /* a(i-5)   */
                seq_t term3 = cache[i - 7];   /* a(i-6)   */
                val = term1 + (seq_t)11 * term2 - (seq_t)11 * term3;
            }
            cache[i - 1] = val;
        }
        cache_len = (size_t)n;
    }

    return cache[n - 1];
}
